        private static readonly string[] SqlIndentifiers = new[] { "SELECT ", "INSERT ", "UPDATE ", "DELETE ", "CREATE ", "ALTER ", "DROP ", "TRUNCATE ", "EXECUTE ", "EXEC ", "EXECUTE IMMEDIATE", "JOIN " };
