        private static readonly string[] IgnoreForCodeRuleAnalyse = Array.Empty<string>();


        [AssemblyInitialize]
        public static void Init(TestContext _)
        {
            var solutionFileInfo = new SolutionFileName("AspNetCore.MinimalApi.Sdk.sln").FindSolutionFileReverseFrom(new DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory));
            Throw.IfNull(solutionFileInfo);

